        if 'message' in msg and 'content' in msg['message']:
            for c in msg['message']['content']:
                if isinstance(c, dict) and 'text' in c:
                    full_text += c.get('text', '')

        # Extract Demo 1 input
        m_in = re.search(r'Demo pair 1 input \((\d+)x(\d+)\):\n(.+?)(?=Demo pair 1 output|$)', full_text, re.DOTALL)
        if m_in and demo_in is None:
            h, w = int(m_in.group(1)), int(m_in.group(2))
            demo_in = [[int(x) for x in r.split()] for r in m_in.group(3).split('\n')[:h]]
            print(f"Demo 1 Input: {h}x{w}")

        # Extract Demo 1 output  
        m_out = re.search(r'Demo pair 1 output \((\d+)x(\d+)\):\n(.+?)(?:Demo pair|Test input|$)', full_text, re.DOTALL)
        if m_out and demo_out is None:
            h, w = int(m_out.group(1)), int(m_out.group(2))
            demo_out = [[int(x) for x in r.split()] for r in m_out.group(3).split('\n')[:h]]
            print(f"Demo 1 Output: {h}x{w}")

    except Exception as e:
        continue

if demo_in and demo_out:
    print("\n=== Verifying Demo 1 ===")

    # Try different rules

    # Rule A: Between any two 0s horizontally, fill with 2s (keep existing 0s)
    def rule_horizontal(grid):
        result = []
        for row in grid:
            new_row = []
            i = 0
            while i < len(row):
                if row[i] == 0:
                    new_row.append(0)
                    j = i + 1
                    # Skip consecutive 0s
                    while j < len(row) and row[j] == 0:
                        j += 1
                    if j < len(row):
                        for k in range(i+1, j):
                            new_row.append(2)  # All cells between first and next 0 become 2
                    else:
                        for k in range(i+1, len(row)):
                            new_row.append(2)  # Fill to end
                else:
                    new_row.append(row[i])
                i += 1
            result.append(new_row)
        return result

    pred_A = rule_horizontal(demo_in)
    match_A = all(all(a==b for a,b in zip(ra,rb)) for ra,rb in zip(demo_out, pred_A))
    print(f"Rule A (fill between first and next 0): {match_A}")

    # Show where they differ
